				state.grpOptions.group.members[state.curSelected].set_antialiasing(backend_ClientPrefs.data.antialiasing);
				if(state.progressBar.visible) {
					if(state.barTween != null) {
						state.barTween.cancel();
					}
					state.barTween = flixel_tweens_FlxTween.tween(state.progressBar,{ percent : 0},0.5,{ ease : flixel_tweens_FlxEase.quadOut, onComplete : function(twn) {
						state.progressBar.updateBar();
					}, onUpdate : function(twn) {
						state.progressBar.updateBar();
					}});
				}
				backend_Achievements.save();
				flixel_FlxG.save.flush();
				flixel_FlxG.sound.play(backend_Paths.returnSound("sounds/" + "cancelMenu",null,true));
