	,fullComboFunction: function() {
		var sicks = this.ratingsData[0].hits;
		var goods = this.ratingsData[1].hits;
		var bads = this.ratingsData[2].hits;
		var shits = this.ratingsData[3].hits;
		this.ratingFC = "";
		if(this.songMisses == 0) {
			if(bads > 0 || shits > 0) {
				this.ratingFC = "FC";
			} else if(goods > 0) {
				this.ratingFC = "GFC";
			} else if(sicks > 0) {
				this.ratingFC = "SFC";
			}
		} else if(this.songMisses < 10) {
			this.ratingFC = "SDCB";
		} else {
			this.ratingFC = "Clear";
		}
	}
	,doScoreBop: function() {
		var _gthis = this;
		if(!backend_ClientPrefs.data.scoreZoom) {
			return;
		}
		if(this.scoreTxtTween != null) {
			this.scoreTxtTween.cancel();
		}
		this.scoreTxt.scale.set_x(1.075);
		this.scoreTxt.scale.set_y(1.075);
		this.scoreTxtTween = flixel_tweens_FlxTween.tween(this.scoreTxt.scale,{ x : 1, y : 1},0.2,{ onComplete : function(twn) {
			_gthis.scoreTxtTween = null;
		}});
	}
	,setSongTime: function(time) {
		flixel_FlxG.sound.music.pause();
		this.vocals.pause();
		this.opponentVocals.pause();
		flixel_FlxG.sound.music.set_time(time - backend_Conductor.offset);
		flixel_FlxG.sound.music.set_pitch(this.playbackRate);
		flixel_FlxG.sound.music.play();
		if(backend_Conductor.songPosition < this.vocals._length) {
			this.vocals.set_time(time - backend_Conductor.offset);
			this.vocals.set_pitch(this.playbackRate);
			this.vocals.play();
		} else {
			this.vocals.pause();
		}
		if(backend_Conductor.songPosition < this.opponentVocals._length) {
			this.opponentVocals.set_time(time - backend_Conductor.offset);
			this.opponentVocals.set_pitch(this.playbackRate);
			this.opponentVocals.play();
		} else {
			this.opponentVocals.pause();
		}
		backend_Conductor.songPosition = time;
	}
