	,reloadCharacterImage: function() {
		var lastAnim = this.character._lastPlayedAnimation;
		var anims = this.character.animationsArray.slice();
		this.character.atlas = flixel_util_FlxDestroyUtil.destroy(this.character.atlas);
		this.character.isAnimateAtlas = false;
		this.character.set_color(-1);
		this.character.set_alpha(1);
		if(backend_Paths.fileExists("images/" + this.character.imageFile + "/Animation.json","TEXT")) {
			this.character.atlas = new flxanimate_PsychFlxAnimate();
			this.character.atlas.set_showPivot(false);
			try {
				backend_Paths.loadAnimateAtlas(this.character.atlas,this.character.imageFile);
			} catch( _g ) {
				haxe_NativeStackTrace.lastError = _g;
				var e = haxe_Exception.caught(_g).unwrap();
				flixel_FlxG.log.advanced("Could not load atlas " + this.character.imageFile + ": " + Std.string(e),flixel_system_debug_log_LogStyle.WARNING,true);
			}
			this.character.isAnimateAtlas = true;
		} else {
			this.character.set_frames(backend_Paths.getMultiAtlas(this.character.imageFile.split(",")));
		}
		var _g = 0;
		while(_g < anims.length) {
			var anim = anims[_g];
			++_g;
			var animAnim = "" + anim.anim;
			var animName = "" + anim.name;
			var animFps = anim.fps;
			var animLoop = anim.loop;
			var animIndices = anim.indices;
			this.addAnimation(animAnim,animName,animFps,animLoop,animIndices);
		}
		if(anims.length > 0) {
			if(lastAnim != "") {
				this.character.playAnim(lastAnim,true);
			} else {
				this.character.dance();
			}
		}
	}
