	,reloadNotesDropdowns: function() {
		if(this.eventDropDown != null) {
			this.eventsList = [];
			var eventFiles = this.loadFileList("custom_events/",null,[".txt"]);
			var _g = 0;
			while(_g < eventFiles.length) {
				var file = eventFiles[_g];
				++_g;
				var path = backend_Paths.getPath("custom_events/" + file + ".txt","TEXT",null,true);
				var desc = openfl_utils_Assets.exists(path,"TEXT") ? lime_utils_Assets.getText(path) : null;
				this.eventsList.push([file,desc]);
			}
			var _g_current = 0;
			var _g_array = states_editors_ChartingState.defaultEvents;
			while(_g_current < _g_array.length) {
				var _g_value = _g_array[_g_current];
				var _g_key = _g_current++;
				var id = _g_key;
				var event = _g_value;
				if(this.eventsList.indexOf(event) == -1) {
					this.eventsList.splice(id,0,event);
				}
			}
			var displayEventsList = [];
			var _g_current = 0;
			var _g_array = this.eventsList;
			while(_g_current < _g_array.length) {
				var _g_value = _g_array[_g_current];
				var _g_key = _g_current++;
				var id = _g_key;
				var data = _g_value;
				if(id > 0) {
					displayEventsList[id] = "" + id + ". " + data[0];
				} else {
					displayEventsList.push("");
				}
			}
			var lastSelected = this.eventDropDown.selectedLabel;
			this.eventDropDown.set_list(displayEventsList);
			this.eventDropDown.set_selectedLabel(lastSelected);
		}
		if(this.noteTypeDropDown != null) {
			var exts = [".txt"];
			this.noteTypes = this.loadFileList("custom_notetypes/",null,exts);
			var _g_current = 0;
			var _g_array = objects_Note.defaultNoteTypes;
			while(_g_current < _g_array.length) {
				var _g_value = _g_array[_g_current];
				var _g_key = _g_current++;
				var id = _g_key;
				var noteType = _g_value;
				if(this.noteTypes.indexOf(noteType) == -1) {
					this.noteTypes.splice(id,0,noteType);
				}
			}
			if(backend_Song.chartPath != null && backend_Song.chartPath.length > 0) {
				var parentFolder = StringTools.replace(backend_Song.chartPath,"\\","/");
				parentFolder = HxOverrides.substr(parentFolder,0,backend_Song.chartPath.lastIndexOf("/") + 1);
				var path = parentFolder + "notetypes.txt";
				var daList = null;
				if(openfl_utils_Assets.exists(path)) {
					daList = openfl_utils_Assets.getText(path);
				}
				var notetypeFile;
				if(daList != null) {
					var daList1 = [];
					daList1 = StringTools.trim(daList).split("\n");
					var _g = 0;
					var _g1 = daList1.length;
					while(_g < _g1) {
						var i = _g++;
						daList1[i] = StringTools.trim(daList1[i]);
					}
					notetypeFile = daList1;
				} else {
					notetypeFile = [];
				}
				if(notetypeFile.length > 0) {
					var _g = 0;
					while(_g < notetypeFile.length) {
						var ntTyp = notetypeFile[_g];
						++_g;
						var name = StringTools.trim(ntTyp);
						if(this.noteTypes.indexOf(name) == -1) {
							this.noteTypes.push(name);
						}
					}
				}
			}
			var displayNoteTypes = this.noteTypes.slice();
			var _g_current = 0;
			var _g_array = displayNoteTypes;
			while(_g_current < _g_array.length) {
				var _g_value = _g_array[_g_current];
				var _g_key = _g_current++;
				var id = _g_key;
				var key = _g_value;
				if(id == 0) {
					continue;
				}
				displayNoteTypes[id] = "" + id + ". " + key;
			}
			var lastSelected = this.noteTypeDropDown.selectedLabel;
			this.noteTypeDropDown.set_list(displayNoteTypes);
			this.noteTypeDropDown.set_selectedLabel(lastSelected);
		}
	}
	,pasteCopiedNotesToSection: function(canCopyNotes,canCopyEvents,showMessage) {
		if(showMessage == null) {
			showMessage = true;
		}
		if(canCopyEvents == null) {
			canCopyEvents = true;
		}
		if(canCopyNotes == null) {
			canCopyNotes = true;
		}
		var curSectionTime = this.cachedSectionTimes[this.curSec];
		if(curSectionTime == null) {
			this.showOutput("ERROR: Unknown section??",true);
			return [];
		}
		var pushedNotes = [];
		var nts = [];
		var evs = [];
		if(canCopyNotes && this.copiedNotes.length > 0) {
			var _g = 0;
			var _g1 = this.copiedNotes;
			while(_g < _g1.length) {
				var note = _g1[_g];
				++_g;
				if(note == null) {
					continue;
				}
				var dataCopy = this.makeNoteDataCopy(note,false);
				dataCopy[0] += curSectionTime;
				var createdNote = this.createNote(dataCopy,this.curSec);
				this.notes.push(createdNote);
				pushedNotes.push(createdNote);
				nts.push(createdNote);
			}
			this.notes.sort(states_PlayState.sortByTime);
		}
		if(canCopyEvents && this.copiedEvents.length > 0) {
			var _g = 0;
			var _g1 = this.copiedEvents;
			while(_g < _g1.length) {
				var event = _g1[_g];
				++_g;
				if(event == null) {
					continue;
				}
				var dataCopy = this.makeNoteDataCopy(event,true);
				dataCopy[0] += curSectionTime;
				var createdEvent = this.createEvent(dataCopy);
				this.events.push(createdEvent);
				pushedNotes.push(createdEvent);
				evs.push(createdEvent);
			}
			this.events.sort(states_PlayState.sortByTime);
		}
		this.loadSection();
		if(showMessage) {
			if(nts.length == 0 && evs.length == 0) {
				this.showOutput("Nothing to paste!",true);
				return [];
			}
			var str = "";
			if(nts.length > 0) {
				str += "Notes Added: " + nts.length;
			}
			if(evs.length > 0) {
				if(str.length > 0) {
					str += "\n";
				}
				str += "Events Added: " + evs.length;
			}
			if(str.length > 0) {
				this.showOutput(str);
			}
		}
		this.addUndoAction("Add Note",{ notes : nts, events : evs});
		return pushedNotes;
	}
