	,updateChartData: function() {
		var _g_current = 0;
		var _g_array = states_PlayState.SONG.notes;
		while(_g_current < _g_array.length) {
			var _g_value = _g_array[_g_current];
			var _g_key = _g_current++;
			var secNum = _g_key;
			var section = _g_value;
			states_PlayState.SONG.notes[secNum].sectionNotes = [];
		}
		this.notes.sort(states_PlayState.sortByTime);
		var noteSec = 0;
		var nextSectionTime = this.cachedSectionTimes[noteSec + 1];
		var curSectionTime = this.cachedSectionTimes[noteSec];
		var _g_current = 0;
		var _g_array = this.notes;
		while(_g_current < _g_array.length) {
			var _g_value = _g_array[_g_current];
			var _g_key = _g_current++;
			var num = _g_key;
			var note = _g_value;
			if(note == null) {
				continue;
			}
			while(this.cachedSectionTimes[noteSec + 1] <= note.strumTime) {
				++noteSec;
				nextSectionTime = this.cachedSectionTimes[noteSec + 1];
				curSectionTime = this.cachedSectionTimes[noteSec];
			}
			var arr = states_PlayState.SONG.notes[noteSec].sectionNotes;
			arr.push(note.songData);
		}
		this.events.sort(states_PlayState.sortByTime);
		states_PlayState.SONG.events = [];
		var _g = 0;
		var _g1 = this.events;
		while(_g < _g1.length) {
			var event = _g1[_g];
			++_g;
			states_PlayState.SONG.events.push(event.songData);
		}
	}
	,saveChart: function(canQuickSave) {
		if(canQuickSave == null) {
			canQuickSave = true;
		}
		var _gthis = this;
		this.updateChartData();
		var chartData = states_editors_content_PsychJsonPrinter.print(states_PlayState.SONG,["sectionNotes","events"]);
		if(canQuickSave && backend_Song.chartPath != null) {
			states_editors__$ChartingState_File.saveContent(backend_Song.chartPath,chartData);
			this.showOutput("Chart saved successfully to: " + backend_Song.chartPath);
		} else {
			var path = states_PlayState.SONG.song;
			var invalidChars_r = new RegExp("[~&;:<>#\\s]","g".split("u").join(""));
			var hideChars_r = new RegExp("[.,'\"%?!]","g".split("u").join(""));
			var chartName = StringTools.trim(path.replace(invalidChars_r,"-").replace(hideChars_r,"")).toLowerCase() + ".json";
			if(backend_Song.chartPath != null) {
				chartName = StringTools.trim(HxOverrides.substr(backend_Song.chartPath,backend_Song.chartPath.lastIndexOf("/"),null));
			}
			this.fileDialog.save(chartName,chartData,function() {
				var newPath = _gthis.fileDialog.path;
				backend_Song.chartPath = StringTools.replace(newPath,"\\","/");
				_gthis.reloadNotesDropdowns();
				_gthis.showOutput("Chart saved successfully to: " + newPath);
			},null,function() {
				_gthis.showOutput("Error on saving chart!",true);
			});
		}
	}
