	,updateCharTypeBox: function() {
		switch(this.character.jsonFile.dialogue_pos) {
		case "center":
			this.characterTypeRadio.set_checked(1);
			break;
		case "left":
			this.characterTypeRadio.set_checked(0);
			break;
		default:
			this.characterTypeRadio.set_checked(2);
		}
		this.reloadCharacter();
		this.updateTextBox();
	}
	,reloadCharacter: function() {
		var charsArray = [this.character,this.ghostLoop,this.ghostIdle];
		var _g = 0;
		while(_g < charsArray.length) {
			var char = charsArray[_g];
			++_g;
			var key = "dialogue/" + this.character.jsonFile.image;
			var parentFolder = null;
			if(key.indexOf("psychic") != -1) {
				haxe_Log.trace(key,{ fileName : "source/backend/Paths.hx", lineNumber : 382, className : "backend.Paths", methodName : "getSparrowAtlas", customParams : [parentFolder,true]});
			}
			var imageLoaded = backend_Paths.image(key,parentFolder,true);
			var key1 = "images/" + key;
			var this1 = backend_Language.phrases;
			var key2 = StringTools.trim(key1).toLowerCase();
			var str = this1.h[key2];
			if(str != null) {
				key1 = str;
			}
			char.set_frames(flixel_graphics_frames_FlxAtlasFrames.fromSparrow(imageLoaded,backend_Paths.getPath(key1 + ".xml","TEXT",parentFolder)));
			char.jsonFile = this.character.jsonFile;
			char.reloadAnimations();
			char.setGraphicSize(char.get_width() * cutscenes_DialogueCharacter.DEFAULT_SCALE * this.character.jsonFile.scale | 0);
			char.updateHitbox();
		}
		this.character.set_x(cutscenes_DialogueBoxPsych.LEFT_CHAR_X);
		this.character.set_y(cutscenes_DialogueBoxPsych.DEFAULT_CHAR_Y);
		switch(this.character.jsonFile.dialogue_pos) {
		case "center":
			this.character.set_x(flixel_FlxG.width / 2);
			var fh = this.character;
			fh.set_x(fh.x - this.character.get_width() / 2);
			break;
		case "right":
			this.character.set_x(flixel_FlxG.width - this.character.get_width() + cutscenes_DialogueBoxPsych.RIGHT_CHAR_X);
			break;
		}
		var fh = this.character;
		fh.set_x(fh.x + (this.character.jsonFile.position[0] + this.mainGroup.x));
		var fh = this.character;
		fh.set_y(fh.y + (this.character.jsonFile.position[1] + this.mainGroup.y));
		this.character.playAnim(this.character.jsonFile.animations[0].anim);
		if(this.character.jsonFile.animations.length > 0) {
			this.curSelectedAnim = this.character.jsonFile.animations[0].anim;
			var animShit = this.character.dialogueAnimations.h[this.curSelectedAnim];
			this.ghostLoop.playAnim(animShit.anim);
			this.ghostIdle.playAnim(animShit.anim,true);
			this.offsetLoopText.set_text("Loop: " + Std.string(animShit.loop_offsets));
			this.offsetIdleText.set_text("Idle: " + Std.string(animShit.idle_offsets));
		}
		this.curAnim = 0;
		this.animText.set_text("Animation: " + this.character.jsonFile.animations[this.curAnim].anim + " (" + (this.curAnim + 1) + " / " + this.character.jsonFile.animations.length + ") - Press W or S to scroll");
		backend_DiscordClient.changePresence("Dialogue Character Editor","Editting: " + this.character.jsonFile.image);
	}
	,updateTextBox: function() {
		this.box.set_flipX(false);
		var anim = "normal";
		switch(this.character.jsonFile.dialogue_pos) {
		case "center":
			anim = "center";
			break;
		case "left":
			this.box.set_flipX(true);
			break;
		}
		this.box.animation.play(anim,true);
		cutscenes_DialogueBoxPsych.updateBoxOffsets(this.box);
	}
	,UIEvent: function(id,sender) {
		if(id == backend_ui_PsychUICheckBox.CLICK_EVENT) {
			this.unsavedProgress = true;
		}
		if(id == backend_ui_PsychUIInputText.CHANGE_EVENT && sender == this.imageInputText) {
			this.character.jsonFile.image = this.imageInputText.text;
			this.unsavedProgress = true;
		} else if(id == backend_ui_PsychUINumericStepper.CHANGE_EVENT && ((sender) instanceof backend_ui_PsychUINumericStepper)) {
			if(sender == this.scaleStepper) {
				this.character.jsonFile.scale = this.scaleStepper.value;
				this.reloadCharacter();
			} else if(sender == this.xStepper) {
				this.character.jsonFile.position[0] = this.xStepper.value;
				this.reloadCharacter();
			} else if(sender == this.yStepper) {
				this.character.jsonFile.position[1] = this.yStepper.value;
				this.reloadCharacter();
			}
			this.unsavedProgress = true;
		}
	}
