	,addAnimTab: function() {
		var _gthis = this;
		var UI = this.UI.getTab("Animation").menu;
		UI.add(new flixel_text_FlxText(20,20,0,"Animation Name:",8));
		var name_input = new backend_ui_PsychUIInputText(20,37.5,100,"",8);
		name_input.name = "name_input";
		this.curAnimText = name_input;
		UI.add(name_input);
		UI.add(new flixel_text_FlxText(name_input.x,name_input.y + 30,0,"Animation Prefix:",8));
		var prefix_input = new backend_ui_PsychUIInputText(20,name_input.y + 47.5,100,"",8);
		UI.add(prefix_input);
		UI.add(new flixel_text_FlxText(150,20,0,"Note Data:"));
		this.numericStepperData = new backend_ui_PsychUINumericStepper(150,37.5,1,.0,.0,999,0);
		UI.add(this.numericStepperData);
		UI.add(new flixel_text_FlxText(150,name_input.y + 30,0,"Indices (OPTIONAL):"));
		var indices_input = new backend_ui_PsychUIInputText(150,name_input.y + 47.5,100,"",8);
		UI.add(indices_input);
		UI.add(new flixel_text_FlxText(20,110,0,"Minimum FPS:"));
		var minFps = new backend_ui_PsychUINumericStepper(20,127.5,1,22,1,120);
		UI.add(minFps);
		UI.add(new flixel_text_FlxText(150,110,0,"Maximum FPS:"));
		var maxFps = new backend_ui_PsychUINumericStepper(150,127.5,1,26,1,120);
		UI.add(maxFps);
		this.animDropDown = new backend_ui_PsychUIDropDownMenu(-155,57,[""],function(id,name) {
			if(_gthis.config != null && name.length > 0) {
				var i = _gthis.config.animations.h[name];
				if(i != null) {
					name_input.set_text(name);
					prefix_input.set_text(i.prefix);
					_gthis.numericStepperData.set_min(0);
					_gthis.numericStepperData.set_value(i.noteData);
					_gthis.curAnim = name;
					minFps.set_value(i.fps[0]);
					maxFps.set_value(i.fps[1]);
					if(i.indices != null && i.indices.length > 0) {
						indices_input.set_text(i.indices.toString().substring(1,i.indices.toString().length - 2));
					}
					_gthis.playStrumAnim(_gthis.curAnim,i.noteData);
				}
			}
		});
		var setAnimDropDown = function() {
			var anims = [];
			if(_gthis.config != null && _gthis.config.animations != null) {
				var h = _gthis.config.animations.h;
				var i_h = h;
				var i_keys = Object.keys(h);
				var i_length = i_keys.length;
				var i_current = 0;
				while(i_current < i_length) {
					var i = i_keys[i_current++];
					anims.push(i);
				}
			}
			if(anims.length < 1) {
				anims.push("");
			}
			if(_gthis.curAnim == null && anims[0].length > 0) {
				_gthis.curAnim = anims[0];
			}
			_gthis.animDropDown.set_list(anims);
			_gthis.animDropDown.set_selectedLabel(_gthis.curAnim);
		};
		setAnimDropDown();
		this.templateButton.onClick = function() {
			objects_NoteSplash.configs.h = Object.create(null);
			_gthis.config = objects_NoteSplash.createConfig();
			_gthis.curAnim = null;
			name_input.set_text("");
			prefix_input.set_text("");
			indices_input.set_text("");
			_gthis.numericStepperData.set_value(0);
			minFps.set_value(22);
			maxFps.set_value(26);
			setAnimDropDown();
			_gthis.parseRGB();
			_gthis.changeShader.set_selectedLabel("Red");
			_gthis.changeShader.onSelect(0,"Red");
		};
		this.addButton = new backend_ui_PsychUIButton(20,185,"Add/Update",function() {
			var indices = [];
			if(indices_input.text.split(",").length > 1) {
				var _g = 0;
				var _g1 = indices_input.text.split(",");
				while(_g < _g1.length) {
					var i = _g1[_g];
					++_g;
					var index = Std.parseInt(i);
					if(!isNaN(index) && index != null) {
						indices.push(index);
					}
				}
			}
			var offsets = [0,0];
			var conf = _gthis.config.animations.h[name_input.text];
			if(conf != null) {
				offsets = conf.offsets;
			}
			if(offsets == null) {
				offsets = [0,0];
			} else {
				offsets = offsets.slice();
			}
			_gthis.config = objects_NoteSplash.addAnimationToConfig(_gthis.config,_gthis.scaleNumericStepper.value,name_input.text,prefix_input.text,[minFps.value,maxFps.value],offsets,indices,_gthis.numericStepperData.value);
			_gthis.curAnim = name_input.text;
			_gthis.playStrumAnim(_gthis.curAnim,_gthis.numericStepperData.value);
			setAnimDropDown();
		});
		UI.add(this.addButton);
		var removeButton = new backend_ui_PsychUIButton(185,185,"Remove",function() {
			if(_gthis.config != null) {
				if(Object.prototype.hasOwnProperty.call(_gthis.config.animations.h,_gthis.curAnim)) {
					var key = _gthis.curAnim;
					var _this = _gthis.config.animations;
					if(Object.prototype.hasOwnProperty.call(_this.h,key)) {
						delete(_this.h[key]);
					}
					_gthis.curAnim = null;
					name_input.set_text("");
					prefix_input.set_text("");
					indices_input.set_text("");
					_gthis.numericStepperData.set_value(0);
					setAnimDropDown();
				}
			}
		});
		UI.add(removeButton);
		UI.add(this.animDropDown);
		this.reloadImage = function() {
			states_editors_NoteSplashEditorState.imageSkin = _gthis.imageInputText.text;
			_gthis.errorText.set_color(-65536);
			flixel_tweens_FlxTween.cancelTweensOf(_gthis.errorText);
			var image = backend_Paths.image(states_editors_NoteSplashEditorState.imageSkin);
			if(image == null) {
				_gthis.errorText.set_text("ERROR! Couldn't find " + states_editors_NoteSplashEditorState.imageSkin + ".png");
				_gthis.errorText.set_alpha(1);
				return;
			} else {
				_gthis.errorText.set_color(-16744448);
				_gthis.errorText.set_alpha(1);
				_gthis.errorText.set_text("Succesfully loaded " + states_editors_NoteSplashEditorState.imageSkin + ".png");
			}
			objects_NoteSplash.configs.h = Object.create(null);
			flixel_tweens_FlxTween.tween(_gthis.errorText,{ alpha : 0},1,{ startDelay : 1, onComplete : function(twn) {
				_gthis.errorText.set_color(-65536);
			}});
			_gthis.splash.loadSplash(states_editors_NoteSplashEditorState.imageSkin);
			_gthis.splash.set_alpha(0.0001);
			if(_gthis.splash.config != null) {
				_gthis.config = _gthis.splash.config;
			} else {
				_gthis.config = objects_NoteSplash.createConfig();
			}
			_gthis.curAnim = null;
			name_input.set_text("");
			prefix_input.set_text("");
			indices_input.set_text("");
			_gthis.numericStepperData.set_value(0);
			minFps.set_value(22);
			maxFps.set_value(26);
			setAnimDropDown();
			_gthis.parseRGB();
			_gthis.changeShader.set_selectedLabel("Red");
			_gthis.changeShader.onSelect(0,"Red");
		};
	}
