	,addShadersTab: function() {
		var _gthis = this;
		var tab = this.shaderUI.getTab("Shader").menu;
		tab.add(new flixel_text_FlxText(40,10,null,"Replacing Color:"));
		tab.add(new flixel_text_FlxText(25,30,null,"Red:"));
		tab.add(new flixel_text_FlxText(25,50,null,"Green:"));
		tab.add(new flixel_text_FlxText(25,70,null,"Blue:"));
		var red = new backend_ui_PsychUINumericStepper(60,30,1,this.redShader[0],0,255,0);
		red.onValueChange = function() {
			var shader;
			switch(_gthis.changeShader.selectedLabel) {
			case "Green":
				shader = _gthis.greenShader[0] = red.value | 0;
				break;
			case "Red":
				shader = _gthis.redShader[0] = red.value | 0;
				break;
			default:
				shader = _gthis.blueShader[0] = red.value | 0;
			}
			_gthis.setConfigRGB();
		};
		tab.add(red);
		var green = new backend_ui_PsychUINumericStepper(60,50,1,this.redShader[1],0,255,0);
		green.onValueChange = function() {
			var shader;
			switch(_gthis.changeShader.selectedLabel) {
			case "Green":
				shader = _gthis.greenShader[1] = green.value | 0;
				break;
			case "Red":
				shader = _gthis.redShader[1] = green.value | 0;
				break;
			default:
				shader = _gthis.blueShader[1] = green.value | 0;
			}
			_gthis.setConfigRGB();
		};
		tab.add(green);
		var blue = new backend_ui_PsychUINumericStepper(60,70,1,this.redShader[2],0,255,0);
		blue.onValueChange = function() {
			var shader;
			switch(_gthis.changeShader.selectedLabel) {
			case "Green":
				shader = _gthis.greenShader[2] = blue.value | 0;
				break;
			case "Red":
				shader = _gthis.redShader[2] = blue.value | 0;
				break;
			default:
				shader = _gthis.blueShader[2] = blue.value | 0;
			}
			_gthis.setConfigRGB();
		};
		tab.add(blue);
		var onCheck = function(change) {
			if(change == null) {
				change = true;
			}
			if(!_gthis.defaultButton.checked) {
				_gthis.shaderUI.set_alpha(1);
			} else {
				_gthis.shaderUI.set_alpha(0.6);
			}
			if(change) {
				switch(_gthis.changeShader.selectedLabel) {
				case "Blue":
					_gthis.blueEnabled = !_gthis.defaultButton.checked;
					break;
				case "Green":
					_gthis.greenEnabled = !_gthis.defaultButton.checked;
					break;
				case "Red":
					_gthis.redEnabled = !_gthis.defaultButton.checked;
					break;
				}
			}
			_gthis.setConfigRGB();
		};
		this.add(new flixel_text_FlxText(this.shaderUI.x + 20,this.shaderUI.y + 135,0,"Color to Replace:"));
		this.changeShader = new backend_ui_PsychUIDropDownMenu(this.shaderUI.x + 20,this.shaderUI.y + 150,["Red","Green","Blue"],function(id,name) {
			var shader;
			switch(name) {
			case "Green":
				shader = _gthis.greenShader;
				break;
			case "Red":
				shader = _gthis.redShader;
				break;
			default:
				shader = _gthis.blueShader;
			}
			red.set_value(shader[0]);
			green.set_value(shader[1]);
			blue.set_value(shader[2]);
			var tmp;
			switch(name) {
			case "Green":
				tmp = !_gthis.greenEnabled;
				break;
			case "Red":
				tmp = !_gthis.redEnabled;
				break;
			default:
				tmp = !_gthis.blueEnabled;
			}
			_gthis.defaultButton.set_checked(tmp);
			onCheck(false);
		});
		this.add(this.changeShader);
		this.defaultButton = new backend_ui_PsychUICheckBox(this.shaderUI.x + 30,this.shaderUI.y + 115,"Do not replace",100,function() {
			onCheck();
		});
		var fh = this.defaultButton.text;
		fh.set_y(fh.y + 2.5);
		this.add(this.defaultButton);
		this.changeShader.set_selectedLabel("Red");
		this.changeShader.onSelect(0,"Red");
	}
