	,getSelected: function(blockReserved) {
		if(blockReserved == null) {
			blockReserved = true;
		}
		var selected = this.spriteListRadioGroup.checked;
		if(selected >= 0) {
			var spr = this.stageSprites[this.spriteListRadioGroup.labels.length - selected - 1];
			if(spr != null && (!blockReserved || backend_StageData.reservedNames.indexOf(spr.type) == -1)) {
				return spr;
			}
		}
		return null;
	}
