	,updateSelectedUI: function() {
		this.posTxt.set_visible(false);
		var selected = this.getSelected(false);
		if(selected == null) {
			return;
		}
		var displayX = Math.round(selected.get_x());
		var displayY = Math.round(selected.get_y());
		var char = selected.sprite;
		if(char != null) {
			displayX -= char.positionArray[0];
			displayY -= char.positionArray[1];
		}
		this.posTxt.set_text("X: " + displayX + "\nY: " + displayY);
		this.posTxt.set_visible(true);
		var selected = this.getSelected();
		if(selected == null) {
			return;
		}
		this.colorInputText.set_text(selected.color);
		this.nameInputText.set_text(selected.name);
		this.imgTxt.set_text("Image: " + selected.image);
		if(selected.type != "square") {
			this.scaleStepperX.set_decimals(this.scaleStepperY.set_decimals(2));
			this.scaleStepperX.set_max(this.scaleStepperY.set_max(10));
			this.scaleStepperX.set_min(this.scaleStepperY.set_min(0.05));
			this.scaleStepperX.step = this.scaleStepperY.step = 0.05;
		} else {
			this.scaleStepperX.set_decimals(this.scaleStepperY.set_decimals(0));
			this.scaleStepperX.set_max(this.scaleStepperY.set_max(10000));
			this.scaleStepperX.set_min(this.scaleStepperY.set_min(50));
			this.scaleStepperX.step = this.scaleStepperY.step = 50;
		}
		this.scaleStepperX.set_value(selected.scale[0]);
		this.scaleStepperY.set_value(selected.scale[1]);
		this.scrollStepperX.set_value(selected.scroll[0]);
		this.scrollStepperY.set_value(selected.scroll[1]);
		this.angleStepper.set_value(selected.get_angle());
		this.alphaStepper.set_value(selected.get_alpha());
		this.antialiasingCheckbox.set_checked(selected.antialiasing);
		this.flipXCheckBox.set_checked(selected.get_flipX());
		this.flipYCheckBox.set_checked(selected.get_flipY());
		this.lowQualityCheckbox.set_checked((selected.filters & 1) == 1);
		this.highQualityCheckbox.set_checked((selected.filters & 2) == 2);
	}
