	,beatHit: function() {
		if(this.currentNeneState._hx_index == 3) {
			if(this.blinkCountdown == 0) {
				flixel_FlxG.game._state.gf.playAnim("idleKnife",false);
				this.blinkCountdown = flixel_FlxG.random.int(this.MIN_BLINK_DELAY,this.MAX_BLINK_DELAY);
			} else {
				this.blinkCountdown--;
			}
		}
		if(backend_ClientPrefs.data.lowQuality) {
			return;
		}
		var Chance = 10;
		if(Chance == null) {
			Chance = 50;
		}
		if(flixel_FlxG.random.float(0,100) < Chance && this.curBeat != this.lastChange + this.changeInterval && this.carInterruptable == true) {
			if(this.lightsStop == false) {
				this.driveCar(this.phillyCars);
			} else {
				this.driveCarLights(this.phillyCars);
			}
		}
		var Chance = 10;
		if(Chance == null) {
			Chance = 50;
		}
		if(flixel_FlxG.random.float(0,100) < Chance && this.curBeat != this.lastChange + this.changeInterval && this.car2Interruptable == true && this.lightsStop == false) {
			this.driveCarBack(this.phillyCars2);
		}
		if(this.curBeat == this.lastChange + this.changeInterval) {
			this.changeLights(this.curBeat);
		}
	}
	,changeLights: function(beat) {
		this.lastChange = beat;
		this.lightsStop = !this.lightsStop;
		if(this.lightsStop) {
			this.phillyTraffic.animation.play("greentored");
			this.changeInterval = 20;
		} else {
			this.phillyTraffic.animation.play("redtogreen");
			this.changeInterval = 30;
			if(this.carWaiting == true) {
				this.finishCarLights(this.phillyCars);
			}
		}
	}
