	,goodNoteHit: function(note) {
		var _gthis = this;
		var Chance = 10;
		if(Chance == null) {
			Chance = 50;
		}
		if(flixel_FlxG.random.float(0,100) < Chance) {
			switch(flixel_FlxG.game._state.combo) {
			case 50:case 100:
				var animToPlay = "combo" + Std.string(flixel_FlxG.game._state.combo);
				if(flixel_FlxG.game._state.gf.animation.exists(animToPlay)) {
					flixel_FlxG.game._state.gf.playAnim(animToPlay);
					flixel_FlxG.game._state.gf.specialAnim = true;
				}
				break;
			}
		}
		switch(note.noteType) {
		case "weekend-1-cockgun":
			flixel_FlxG.game._state.boyfriend.holdTimer = 0;
			flixel_FlxG.game._state.boyfriend.playAnim("cock",true);
			flixel_FlxG.game._state.boyfriend.specialAnim = true;
			this.gunPrepSnd.play();
			flixel_FlxG.game._state.boyfriend.animation.callback = function(name,frameNumber,frameIndex) {
				if(name == "cock") {
					if(frameNumber == 3) {
						flixel_FlxG.game._state.boyfriend.animation.callback = null;
						_gthis.createCasing();
					}
				} else {
					flixel_FlxG.game._state.boyfriend.animation.callback = null;
				}
			};
			flixel_FlxG.game._state.notes.forEachAlive(function(note) {
				if(note.noteType == "weekend-1-firegun") {
					note.blockHit = false;
				}
			});
			this.showPicoFade();
			break;
		case "weekend-1-firegun":
			flixel_FlxG.game._state.boyfriend.holdTimer = 0;
			flixel_FlxG.game._state.boyfriend.playAnim("shoot",true);
			flixel_FlxG.game._state.boyfriend.specialAnim = true;
			var tmp = flixel_FlxG.sound;
			var key = "shots/shot" + flixel_FlxG.random.int(1,4);
			var modsAllowed = true;
			if(modsAllowed == null) {
				modsAllowed = true;
			}
			tmp.play(backend_Paths.returnSound("sounds/" + key,null,modsAllowed));
			this.spraycan.playCanShot();
			new flixel_util_FlxTimer().start(0.041666666666666664,function(tmr) {
				_gthis.darkenStageProps();
			});
			break;
		}
	}
	,createCasing: function() {
		if(backend_ClientPrefs.data.lowQuality) {
			return;
		}
		var casing = new flixel_FlxSprite(flixel_FlxG.game._state.boyfriend.x + 250,flixel_FlxG.game._state.boyfriend.y + 100);
		casing.set_frames(this.casingFrames);
		casing.animation.addByPrefix("pop","Pop0",24,false);
		casing.animation.addByPrefix("idle","Bullet0",24,true);
		casing.animation.play("pop",true);
		casing.animation.callback = function(name,frameNumber,frameIndex) {
			if(name == "pop" && frameNumber == 40) {
				casing.set_x(casing.x + casing.frame.offset.x - 1);
				casing.set_y(casing.y + casing.frame.offset.y + 1);
				casing.set_angle(125.1);
				var randomFactorA = flixel_FlxG.random.float(3,10);
				var randomFactorB = flixel_FlxG.random.float(1.0,2.0);
				casing.velocity.set_x(20 * randomFactorB);
				casing.drag.set_x(randomFactorA * randomFactorB);
				casing.angularVelocity = 100;
				casing.angularDrag = casing.drag.x / casing.velocity.x * 100;
				casing.animation.play("idle");
				casing.animation.callback = null;
			}
		};
		this.casingGroup.add(casing);
	}
	,opponentNoteHit: function(note) {
		var _gthis = this;
		var sndTime = note.strumTime - backend_Conductor.songPosition;
		switch(note.noteType) {
		case "weekend-1-kickcan":
			flixel_FlxG.game._state.dad.holdTimer = 0;
			flixel_FlxG.game._state.dad.playAnim("kickCan",true);
			flixel_FlxG.game._state.dad.specialAnim = true;
			this.kickCanSnd.play(true,sndTime - 50);
			this.spraycan.playCanStart();
			var fh = flixel_FlxG.game._state.camFollow;
			fh.set_x(fh.x + 250);
			flixel_FlxG.game._state.cameraSpeed = 1.5;
			flixel_FlxG.game._state.defaultCamZoom -= 0.1;
			new flixel_util_FlxTimer().start(1.1,function(_) {
				flixel_FlxG.game._state.isCameraOnForcedPos = false;
				flixel_FlxG.game._state.moveCameraSection();
				flixel_FlxG.game._state.cameraSpeed = 1;
			});
			break;
		case "weekend-1-kneecan":
			flixel_FlxG.game._state.dad.holdTimer = 0;
			flixel_FlxG.game._state.dad.playAnim("kneeCan",true);
			flixel_FlxG.game._state.dad.specialAnim = true;
			this.kneeCanSnd.play(true,sndTime - 22);
			break;
		case "weekend-1-lightcan":
			flixel_FlxG.game._state.dad.holdTimer = 0;
			flixel_FlxG.game._state.dad.playAnim("lightCan",true);
			flixel_FlxG.game._state.dad.specialAnim = true;
			this.lightCanSnd.play(true,sndTime - 65);
			flixel_FlxG.game._state.isCameraOnForcedPos = true;
			flixel_FlxG.game._state.defaultCamZoom += 0.1;
			flixel_FlxG.game._state.moveCamera(true);
			flixel_FlxG.game._state.cameraSpeed = 2;
			var fh = flixel_FlxG.game._state.camFollow;
			fh.set_x(fh.x - 100);
			break;
		}
	}
