						backend_Song.loadFromJson(poop,songLowercase);
						states_PlayState.storyDifficulty = this.curSelected;
						backend_MusicBeatState.resetState();
						flixel_FlxG.sound.music.set_volume(0);
						states_PlayState.changedDifficulty = true;
						states_PlayState.chartingMode = false;
